function svStripComments(svg){
  return String(svg||'').replace(/<!--[\s\S]*?-->/g,'');
}
function svRoundNums(svg){
  return svg.replace(/(-?\d*\.\d{3,})/g, function(mm){ return (Math.round(parseFloat(mm)*100)/100).toString(); });
}
function svCollapse(svg){
  return svg.replace(/>\s+</g,'><').replace(/\s{2,}/g,' ').replace(/\s+\/>/g,'/>').replace(/\s+=/g,'=').replace(/=\s+/g,'=').trim();
}
function svOptimize(svg){
  return svCollapse(svRoundNums(svStripComments(String(svg||''))));
}
function svStats(orig, opt){
  var o=String(orig||'').length, n=String(opt||'').length;
  return { original:o, optimized:n, saved: o? Math.round((1-n/o)*1000)/10 : 0 };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { svStripComments:svStripComments, svRoundNums:svRoundNums, svCollapse:svCollapse, svOptimize:svOptimize, svStats:svStats };
}
if (typeof window !== 'undefined') {
  window.SvgOptForgePure = { svStripComments:svStripComments, svRoundNums:svRoundNums, svCollapse:svCollapse, svOptimize:svOptimize, svStats:svStats };
}
